import React from "react";
import { useEffect } from "react";
import HelpDocuments from "src/views/pages/ITSolutionDetails/ITSolutionResources/HelpDocuments";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";
import { Box } from "@mui/material";
import { useState } from "react";
import { useAuth } from "src/hooks/useAuth";
import { toastError } from "src/utils/utils";

import { ApiEndpoints } from "src/network/endpoints";
import { axiosInstance } from "src/network/adapter";
import FallbackSpinner from "src/@core/components/spinner";
import { useParams } from "react-router-dom";

const ITSolutionResourcesPage = () => {
  const { setITSolutionId } = useAuth();
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  const [resourcesData, setResourcesData] = useState([]);
  const [resourcesDetails, setResourcesDetails] = useState([]);
  const [resourceTitle, setResourceTitle] = useState("");
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const itSolutionId = id.split("-").pop();
  const [activeButtonID, setActiveButtonID] = useState(null);

  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
    setITSolutionId(itSolutionId);
  }, []);

  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const fetchResourcesData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_RESOURCES.list(itSolutionId))
      .then((response) => {
        const responseData = response.data.data;
        setResourcesData(response.data.data);
        if (responseData.length > 0) {
          fetchResourcesDetailedData(responseData[0].id);
          setActiveButtonID(responseData[0].id);
          setResourceTitle(responseData[0].title); // Assuming 'id' is the identifier for each resource
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const fetchResourcesDetailedData = (resourcesId) => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.IT_SOLUTION_RESOURCES_DETAILS.list(resourcesId))
      .then((response) => {
        setResourcesDetails(response.data.data);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchResourcesData();
  }, [itSolutionId]);

  if (loading) return <FallbackSpinner />;

  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <HelpDocuments
          activeButtonID={activeButtonID}
          resourcesData={resourcesData}
          resourcesDetails={resourcesDetails}
          fetchResourcesDetailedData={fetchResourcesDetailedData}
          resourcesTitle={resourceTitle}
        />
      </Box>
    </>
  );
};

export default ITSolutionResourcesPage;
